const raw = $input.first().json;
const msg = raw.message || {};
const adminId = String($env.ADMIN_TELEGRAM_ID || '0');
const senderId = String(msg.from?.id || '');
const chatId = String(msg.chat?.id || '');
const firstName = msg.from?.first_name || 'cliente';
const text = String(msg.text || msg.caption || '').trim();

// Checar se é arquivo de música (áudio do Telegram ou documento .mp3 / áudio)
const isAudioMusic = !!(msg.audio || (msg.document && (msg.document.mime_type?.startsWith('audio/') || msg.document.file_name?.toLowerCase().endsWith('.mp3'))));
const audioMusicFileId = msg.audio?.file_id || msg.document?.file_id || null;
const audioMusicFileName = msg.audio?.file_name || msg.audio?.title || msg.document?.file_name || 'musica_sarah.mp3';

const fileId = msg.voice?.file_id || (isAudioMusic ? null : msg.audio?.file_id) || msg.video_note?.file_id || null;
const hadVoice = !text && !!fileId && !isAudioMusic;

return [{ json: {
  adminId, senderId, chatId, firstName,
  text: text || (hadVoice ? '' : (isAudioMusic ? '[música para sarah]' : '[mensagem sem texto]')),
  hadVoice, fileId: fileId || '',
  voiceError: '',
  isAudioMusic, audioMusicFileId, audioMusicFileName
} }];

const prep = $('Preparar (texto/voz)').first().json;
const j = $input.first().json || {};
let text = String(j.text || '').trim();
let voiceError = '';
if (!text) {
  voiceError = String(j.error?.message || j.message || 'whisper vazio').slice(0, 180);
  text = '[áudio recebido, mas não consegui transcrever]';
}
return [{ json: { ...prep, text, hadVoice: true, voiceError } }];

function fixTelegramMarkdown(text) {
  if (!text) return '';
  let t = String(text);
  const underscores = (t.match(/_/g) || []).length;
  if (underscores % 2 !== 0) {
    let count = 0;
    t = t.replace(/_/g, m => (++count === underscores ? '' : m));
  }
  const stars = (t.match(/\*/g) || []).length;
  if (stars % 2 !== 0) {
    let count = 0;
    t = t.replace(/\*/g, m => (++count === stars ? '' : m));
  }
  return t;
}

function splitTelegramMessage(text, maxLen = 3800) {
  if (!text) return [''];
  if (text.length <= maxLen) return [text];

  const chunks = [];
  let remaining = text;

  while (remaining.length > maxLen) {
    let splitIdx = remaining.lastIndexOf('\n\n', maxLen);
    if (splitIdx === -1 || splitIdx < maxLen * 0.3) {
      splitIdx = remaining.lastIndexOf('\n', maxLen);
    }
    if (splitIdx === -1 || splitIdx < maxLen * 0.3) {
      splitIdx = remaining.lastIndexOf('. ', maxLen);
      if (splitIdx !== -1) splitIdx += 1;
    }
    if (splitIdx === -1 || splitIdx < maxLen * 0.3) {
      splitIdx = remaining.lastIndexOf(' ', maxLen);
    }
    if (splitIdx === -1 || splitIdx < maxLen * 0.3) {
      splitIdx = maxLen;
    }

    const chunk = remaining.slice(0, splitIdx).trim();
    if (chunk) chunks.push(chunk);
    remaining = remaining.slice(splitIdx).trim();
  }

  if (remaining.length > 0) {
    chunks.push(remaining);
  }
  return chunks;
}

const outItems = [];

for (const item of $input.all()) {
  const rawMsg = item.json.outMessage || item.json.output || item.json.message || '';
  if (!rawMsg) {
    outItems.push(item);
    continue;
  }

  const parts = splitTelegramMessage(rawMsg, 3800);
  for (const part of parts) {
    const fixedPart = fixTelegramMarkdown(part);
    outItems.push({
      json: {
        ...item.json,
        outMessage: fixedPart
      }
    });
  }
}

return outItems;
